create table if not exists public.buildings (
  id uuid primary key,
  name text not null,
  street text not null,
  street_number text,
  neighborhood text not null,
  postal_code text,
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  source_row integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.buildings enable row level security;
drop policy if exists buildings_read_catalog on public.buildings;
create policy buildings_read_catalog on public.buildings for select to authenticated using (true);
revoke all on table public.buildings from anon;
revoke insert, update, delete, truncate, references, trigger on table public.buildings from authenticated;
grant select on table public.buildings to authenticated;

create index if not exists buildings_name_idx on public.buildings(name);
create index if not exists buildings_neighborhood_idx on public.buildings(neighborhood);
create index if not exists buildings_postal_code_idx on public.buildings(postal_code);

drop trigger if exists buildings_set_updated_at on public.buildings;
create trigger buildings_set_updated_at before update on public.buildings
for each row execute function public.set_updated_at();

alter table public.calendar_events
  add column if not exists building_id uuid references public.buildings(id) on delete set null,
  add column if not exists apartment_number text;

create index if not exists calendar_events_user_building_idx
  on public.calendar_events(user_id, building_id)
  where building_id is not null;

on conflict (id) do update set
  name = excluded.name,
  street = excluded.street,
  street_number = excluded.street_number,
  neighborhood = excluded.neighborhood,
  postal_code = excluded.postal_code,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  source_row = excluded.source_row,
  updated_at = now();
